local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServiceDescriptorImplementationTypeResolver = require(script.Parent.ServiceDescriptorImplementationTypeResolver)
local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)
local ServiceProvider = require(script.Parent.ServiceProvider)
local ServiceCollection = require(script.Parent.ServiceCollection)
local LuaTypeProvider = require(script.Parent.LuaTypeProvider)

return function()
	describe("ServiceDescriptorImplementationTypeResolver", function()
		local mockServiceProvider
		local mockLuaTypeProvider

		beforeEach(function()
			mockServiceProvider = {
				GetService = function() end,
			}
			mockLuaTypeProvider = {
				GetType = function() end,
			}
		end)

		it("should handle circular dependencies", function()
			local mockTypeA = {
				new = function() end,
				FullName = "TypeA",
				IsGenericType = false,
				GetConstructors = function()
					return {
						{
							GetParameters = function()
								return { { ParameterType = { FullName = "TypeB" } } }
							end,
						},
					}
				end,
			}
			local mockTypeB = {
				new = function() end,
				FullName = "TypeB",
				IsGenericType = false,
				GetConstructors = function()
					return {
						{
							GetParameters = function()
								return { { ParameterType = { FullName = "TypeA" } } }
							end,
						},
					}
				end,
			}

			mockLuaTypeProvider.GetType = function(typeName)
				if typeName == "TypeA" then
					return mockTypeA
				elseif typeName == "TypeB" then
					return mockTypeB
				else
					error(`type not found: {typeName}`)
				end
			end

			local serviceCollection = ServiceCollection.new()
			serviceCollection:AddSingleton("TypeA", "TypeA")
			serviceCollection:AddSingleton("TypeB", "TypeB")

			local serviceProvider = ServiceProvider.new(nil, serviceCollection, mockLuaTypeProvider)

			local descriptor = ServiceDescriptor.newWithType("TypeA", "TypeA", ServiceLifetime.Singleton)
			local implementationType = descriptor.ImplementationType
			local serviceType = descriptor.ServiceType
			expect(function()
				ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationType(
					serviceProvider,
					"TypeA",
					implementationType,
					serviceType,
					{},
					mockLuaTypeProvider
				)
			end).to.throw("A circular dependency was detected")
		end)
	end)
end
